CREATE SCHEMA IF NOT EXISTS app;
REVOKE ALL ON SCHEMA app FROM PUBLIC;
CREATE TABLE IF NOT EXISTS app.profiles(id uuid PRIMARY KEY, email text NOT NULL, role text NOT NULL DEFAULT 'parent' CHECK(role IN ('parent','provider','admin')), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS app.children(id uuid PRIMARY KEY, parent_id uuid NOT NULL REFERENCES app.profiles, first_name text NOT NULL, surname text NOT NULL, birth_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.providers(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app.profiles, name text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')), description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.activities(id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES app.providers, title text NOT NULL, description text NOT NULL, category text NOT NULL, area text NOT NULL, min_age int NOT NULL CHECK(min_age>=0), max_age int NOT NULL CHECK(max_age>=min_age), price_fils int NOT NULL CHECK(price_fils>0), policy text NOT NULL, published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS app.sessions(id uuid PRIMARY KEY, activity_id uuid NOT NULL REFERENCES app.activities, starts_at timestamptz NOT NULL, cutoff_at timestamptz NOT NULL, capacity int NOT NULL CHECK(capacity>0), allocated int NOT NULL DEFAULT 0 CHECK(allocated>=0 AND allocated<=capacity), CHECK(cutoff_at<starts_at));
CREATE TABLE IF NOT EXISTS app.bookings(id uuid PRIMARY KEY, parent_id uuid NOT NULL REFERENCES app.profiles, provider_id uuid NOT NULL REFERENCES app.providers, session_id uuid NOT NULL REFERENCES app.sessions, state text NOT NULL CHECK(state IN ('REQUESTED','OFFER_PENDING','PAYMENT_DUE','PAYMENT_CHECKING','CONFIRMED','DECLINED','EXPIRED','CANCELLED')), version int NOT NULL DEFAULT 1, quantity int NOT NULL CHECK(quantity>0), amount_fils int NOT NULL CHECK(amount_fils>0), snapshot jsonb NOT NULL, offer jsonb, response_due_at timestamptz NOT NULL, payment_due_at timestamptz, held boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.participants(booking_id uuid NOT NULL REFERENCES app.bookings, child_id uuid NOT NULL REFERENCES app.children, session_id uuid NOT NULL REFERENCES app.sessions, active boolean NOT NULL DEFAULT true, PRIMARY KEY(booking_id,child_id));
CREATE UNIQUE INDEX IF NOT EXISTS active_child_session ON app.participants(child_id,session_id) WHERE active;
CREATE TABLE IF NOT EXISTS app.payments(id uuid PRIMARY KEY, booking_id uuid NOT NULL REFERENCES app.bookings, amount_fils int NOT NULL CHECK(amount_fils>0), reference text NOT NULL, status text NOT NULL CHECK(status IN ('submitted','verified')), submitted_at timestamptz NOT NULL DEFAULT now(), verified_by uuid REFERENCES app.profiles);
CREATE UNIQUE INDEX IF NOT EXISTS one_payment ON app.payments(booking_id);
CREATE TABLE IF NOT EXISTS app.refunds(id uuid PRIMARY KEY, booking_id uuid NOT NULL UNIQUE REFERENCES app.bookings, amount_fils int NOT NULL CHECK(amount_fils>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), evidence text, completed_by uuid REFERENCES app.profiles);
CREATE TABLE IF NOT EXISTS app.subscriptions(provider_id uuid PRIMARY KEY REFERENCES app.providers, plan text NOT NULL, expires_at timestamptz NOT NULL, reference text NOT NULL);
CREATE TABLE IF NOT EXISTS app.corrections(id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES app.providers, activity_id uuid NOT NULL REFERENCES app.activities, message text NOT NULL, status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS app.contacts(id uuid PRIMARY KEY, phone text NOT NULL UNIQUE, name text NOT NULL, marketing text NOT NULL DEFAULT 'unknown' CHECK(marketing IN ('unknown','verified','revoked')), updates text NOT NULL DEFAULT 'unknown', suppressed boolean NOT NULL DEFAULT false, source text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.campaigns(id uuid PRIMARY KEY, name text NOT NULL, template text NOT NULL, language text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status='draft'), created_by uuid NOT NULL REFERENCES app.profiles, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.audit(id uuid PRIMARY KEY, actor_id uuid REFERENCES app.profiles, subject_id uuid NOT NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.outbox(id uuid PRIMARY KEY, booking_id uuid NOT NULL REFERENCES app.bookings, event text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.idempotency(actor_id uuid NOT NULL REFERENCES app.profiles, key text NOT NULL, fingerprint text NOT NULL, response jsonb, PRIMARY KEY(actor_id,key));
CREATE INDEX IF NOT EXISTS booking_queue ON app.bookings(state,response_due_at,payment_due_at);
CREATE INDEX IF NOT EXISTS parent_bookings ON app.bookings(parent_id,created_at DESC);
CREATE INDEX IF NOT EXISTS provider_bookings ON app.bookings(provider_id,created_at DESC);
